Q: How do I add a Marker to a jQuery UI Slider? A: <p>Here is an example that uses the <code>create</code> event to add a Pipe to the element that marks start position.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>$(function() {
  $('#cycle_length').slider({
    range: "min",
    value: 28,
    min: 25,
    max: 35,
    step: 1,
    slide: function(event, ui) {
      $("#amount").val(ui.value);
    },
    create: function() {
      var tick = $("&lt;span&gt;", {
        class: 'ui-slider-tick',
      }).html("|").css({
        left: $(".ui-slider-handle", this).css("left"),
        position: "absolute"
      }).appendTo(this);
    }
  });
  $("#amount").val($("#cycle_length").slider("value"));
});</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;link rel="stylesheet" href="//code.jquery.com/ui/1.10.4/themes/smoothness/jquery-ui.css"&gt;
&lt;script src="//code.jquery.com/jquery-1.10.2.js"&gt;&lt;/script&gt;
&lt;script src="//code.jquery.com/ui/1.10.4/jquery-ui.js"&gt;&lt;/script&gt;

&lt;div id="cycle_length"&gt;&lt;/div&gt;
&lt;div&gt;&lt;input id="amount" type="text"&gt;&lt;/div&gt;</code></pre>
</div>
</div>
